CREATE OR REPLACE FUNCTION gk_private.capture_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE old_doc jsonb; new_doc jsonb; chosen jsonb; keys jsonb := '{}'::jsonb; k text;
BEGIN
 IF TG_OP <> 'INSERT' THEN old_doc := to_jsonb(OLD); END IF;
 IF TG_OP <> 'DELETE' THEN new_doc := to_jsonb(NEW); END IF;
 chosen := COALESCE(new_doc,old_doc);
 FOREACH k IN ARRAY TG_ARGV LOOP keys := keys || jsonb_build_object(k,chosen -> k); END LOOP;
 IF TG_TABLE_NAME='source_records' THEN old_doc := old_doc - 'cell_payload'; new_doc := new_doc - 'cell_payload'; END IF;
 INSERT INTO gk_private.record_audit_events(schema_name,table_name,record_key,operation,before_value,after_value,created_by,updated_by,actor_ref)
 VALUES(TG_TABLE_SCHEMA,TG_TABLE_NAME,keys,TG_OP,old_doc,new_doc,auth.uid(),auth.uid(),CASE WHEN auth.uid() IS NOT NULL THEN 'user:'||auth.uid()::text ELSE 'db:'||session_user||'/role:'||COALESCE(auth.jwt()->>'role','database_owner') END);
 RETURN COALESCE(NEW,OLD);
END;
$function$

CREATE OR REPLACE FUNCTION gk_private.check_answer_kind()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE kind text;
BEGIN
 SELECT value_kind INTO STRICT kind FROM public.questionnaire_items WHERE id=NEW.item_id;
 IF kind='numeric' AND NEW.text_value IS NOT NULL THEN RAISE EXCEPTION 'Numeric item cannot contain text'; END IF;
 IF kind IN ('text','recommendation') AND NEW.numeric_value IS NOT NULL THEN RAISE EXCEPTION 'Text item cannot contain a numeric score'; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION gk_private.check_child_chronology()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE child uuid; joined date; born date; kind text; state text;
BEGIN
 child := (to_jsonb(NEW) ->> CASE WHEN TG_TABLE_NAME='children' THEN 'id' ELSE 'child_id' END)::uuid;
 SELECT joining_date INTO joined FROM public.children WHERE id=child FOR UPDATE;
 SELECT birth_date,origin_kind,review_state INTO born,kind,state FROM gk_private.child_private_profiles WHERE child_id=child;
 IF born > joined AND (kind='manual' OR state='accepted') THEN RAISE EXCEPTION 'Birth/joining chronology conflict requires source review'; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION gk_private.check_reference_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE doc jsonb := to_jsonb(NEW); col text; f text; selected_vocabulary text; selected_code text;
BEGIN
 IF doc ->> 'origin_kind' = 'import' AND doc ->> 'review_state' <> 'accepted' THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='access_memberships' AND doc -> 'active' = 'false'::jsonb THEN RETURN NEW; END IF;
 FOREACH col IN ARRAY TG_ARGV LOOP
  f := split_part(col,':',2); selected_vocabulary := doc ->> split_part(col,':',1); selected_code := doc ->> f;
  IF selected_code IS NOT NULL THEN
   PERFORM 1 FROM public.reference_values r WHERE r.vocabulary=selected_vocabulary AND r.code=selected_code
    AND r.active AND r.review_state='accepted' AND r.archived_at IS NULL FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Selected controlled value is not approved and active'; END IF;
  END IF;
 END LOOP;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION gk_private.is_goalkeep_session()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE claims jsonb := auth.jwt();
BEGIN
 IF auth.uid() IS NULL OR claims ->> 'role' IS DISTINCT FROM 'authenticated' THEN RETURN false; END IF;
 IF claims -> 'app_metadata' ->> 'provider' IS DISTINCT FROM 'google' THEN RETURN false; END IF;
 IF split_part(lower(COALESCE(claims ->> 'email','')),'@',2) <> 'goalkeep.net' THEN RETURN false; END IF;
 IF jsonb_typeof(claims -> 'amr') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(claims -> 'amr') a WHERE a ->> 'method' = 'oauth') THEN RETURN false; END IF;
 RETURN gk_private.is_goalkeep_identity(auth.uid());
END;
$function$

CREATE OR REPLACE FUNCTION gk_private.reject_evidence_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP IN ('DELETE','TRUNCATE') OR TG_TABLE_NAME <> 'source_records' THEN RAISE EXCEPTION 'Evidence is append-only'; END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.artifact_id IS DISTINCT FROM OLD.artifact_id OR NEW.native_sheet_key IS DISTINCT FROM OLD.native_sheet_key
  OR NEW.source_row IS DISTINCT FROM OLD.source_row OR NEW.cell_payload IS DISTINCT FROM OLD.cell_payload THEN RAISE EXCEPTION 'Original source payload and coordinates are immutable'; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION gk_private.reject_identity_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE key_name text;
BEGIN
 FOREACH key_name IN ARRAY TG_ARGV LOOP
  IF to_jsonb(NEW) -> key_name IS DISTINCT FROM to_jsonb(OLD) -> key_name THEN RAISE EXCEPTION 'Identity/definition change requires an explicit correction workflow'; END IF;
 END LOOP;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION gk_private.require_import_provenance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE ok boolean; pointer text := TG_ARGV[0]; target uuid;
BEGIN
 IF NEW.origin_kind <> 'import' THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='reference_values' THEN
  SELECT EXISTS(SELECT 1 FROM gk_private.source_provenance p WHERE p.reference_vocabulary=NEW.vocabulary AND p.reference_code=NEW.code) INTO ok;
 ELSE
  IF pointer <> ALL(ARRAY['child_id','private_profile_child_id','caregiver_id','child_caregiver_id','program_change_id','response_id','item_id','answer_id','attendance_id','support_id','adl_id']) THEN RAISE EXCEPTION 'Invalid typed provenance pointer'; END IF;
  target := (to_jsonb(NEW) ->> TG_ARGV[1])::uuid;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM gk_private.source_provenance WHERE %I = $1)',pointer) INTO ok USING target;
 END IF;
 IF NOT COALESCE(ok,false) THEN RAISE EXCEPTION 'Imported target requires source provenance in the same transaction'; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION gk_private.stamp_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE uid uuid := auth.uid(); is_domain boolean := TG_ARGV[0] = 'domain';
BEGIN
 IF TG_OP = 'INSERT' THEN
  NEW.created_at := now(); NEW.created_by := uid;
 ELSE
  NEW.created_at := OLD.created_at; NEW.created_by := OLD.created_by;
 END IF;
 NEW.updated_at := now(); NEW.updated_by := uid;
 IF auth.jwt() ->> 'role' = 'authenticated' THEN
  IF NOT gk_private.is_goalkeep_session() THEN RAISE EXCEPTION 'Workspace session required'; END IF;
  NEW.actor_ref := 'user:' || uid::text;
  IF is_domain THEN
   IF TG_OP = 'INSERT' AND NEW.origin_kind <> 'manual' THEN RAISE EXCEPTION 'Users cannot impersonate an import job'; END IF;
   IF TG_OP = 'UPDATE' THEN NEW.origin_kind := OLD.origin_kind; END IF;
   IF ((TG_OP = 'INSERT' AND NEW.review_state <> 'pending') OR (TG_OP = 'UPDATE' AND NEW.review_state IS DISTINCT FROM OLD.review_state)) AND NOT gk_private.has_capability('review_data') THEN RAISE EXCEPTION 'Review authorization required'; END IF;
  END IF;
 ELSE
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'service_role' AND session_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'Unidentified database actor'; END IF;
  NEW.actor_ref := 'db:' || session_user || '/role:' || COALESCE(auth.jwt() ->> 'role','database_owner');
 END IF;
 IF TG_ARGV[1] = 'archive' THEN
  IF TG_OP = 'UPDATE' AND NEW.archived_at IS DISTINCT FROM OLD.archived_at THEN
   IF auth.jwt() ->> 'role'='authenticated' AND NOT gk_private.has_capability('soft_delete') THEN RAISE EXCEPTION 'Soft deletion not authorized'; END IF;
   IF NEW.archived_at IS NULL THEN NEW.archived_by := NULL;
   ELSE
    IF uid IS NULL THEN RAISE EXCEPTION 'Soft deletion requires an authenticated accountable user'; END IF;
    NEW.archived_at := now(); NEW.archived_by := uid;
   END IF;
  ELSIF TG_OP='INSERT' AND NEW.archived_at IS NOT NULL THEN RAISE EXCEPTION 'Cannot create an already archived record';
  ELSIF TG_OP='UPDATE' THEN NEW.archived_by := OLD.archived_by;
  END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.gk_manage_membership(p_user uuid, p_role text, p_active boolean, p_private_read boolean, p_private_write boolean, p_approval_reference text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF NOT gk_private.has_capability('manage_access') THEN RAISE EXCEPTION 'Access administration not authorized'; END IF;
 IF p_user = auth.uid() THEN RAISE EXCEPTION 'Self-role or private-access escalation is forbidden'; END IF;
 IF COALESCE(btrim(p_approval_reference),'') = '' THEN RAISE EXCEPTION 'Approval reference required'; END IF;
 -- Revocation must remain possible after identity or role eligibility is lost.
 IF p_active IS FALSE THEN
  UPDATE gk_private.access_memberships SET active=false,private_read=false,private_write=false,
   approval_reference=p_approval_reference WHERE user_id=p_user;
  RETURN;
 END IF;
 IF NOT gk_private.is_goalkeep_identity(p_user) THEN RAISE EXCEPTION 'Target identity is not verified Goalkeep Workspace'; END IF;
 IF p_private_write AND NOT p_private_read THEN RAISE EXCEPTION 'Private write requires private read authorization'; END IF;
 IF (p_private_read OR p_private_write) AND NOT gk_private.has_capability('write_private') THEN RAISE EXCEPTION 'Private authorization exceeds administrator scope'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.reference_values WHERE vocabulary='access_role' AND code=p_role AND active AND review_state='accepted' AND approval_reference IS NOT NULL AND archived_at IS NULL) THEN RAISE EXCEPTION 'Role not approved'; END IF;
 INSERT INTO gk_private.access_memberships(user_id,approved_email_domain,role_code,active,private_read,private_write,approval_reference)
 VALUES(p_user,'goalkeep.net',p_role,p_active,p_private_read,p_private_write,p_approval_reference)
 ON CONFLICT(user_id) DO UPDATE SET role_code=EXCLUDED.role_code,active=EXCLUDED.active,
  private_read=EXCLUDED.private_read,private_write=EXCLUDED.private_write,approval_reference=EXCLUDED.approval_reference;
END;
$function$

CREATE OR REPLACE FUNCTION public.gk_register_member()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE approved_ref text;
BEGIN
 IF NOT gk_private.is_goalkeep_session() THEN RAISE EXCEPTION 'Verified Goalkeep Workspace OAuth session required'; END IF;
 SELECT r.approval_reference INTO approved_ref FROM public.reference_values r
  WHERE r.vocabulary = 'access_role' AND r.code = 'member' AND r.active
   AND r.review_state = 'accepted' AND r.archived_at IS NULL AND r.approval_reference IS NOT NULL;
 IF approved_ref IS NULL THEN RAISE EXCEPTION 'Pilot role matrix not activated by project owner'; END IF;
 INSERT INTO gk_private.access_memberships(user_id,approved_email_domain,role_code,active,private_read,private_write,approval_reference)
 VALUES(auth.uid(),'goalkeep.net','member',true,false,false,approved_ref)
 ON CONFLICT(user_id) DO NOTHING;
 RETURN EXISTS(SELECT 1 FROM gk_private.access_memberships WHERE user_id = auth.uid() AND active AND archived_at IS NULL);
END;
$function$
